code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c]==0 and grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==2:
                centers.append((r,c))
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr or c==cc:
                dr=(rr>r)-(rr<r); dc=(cc>c)-(cc<c)
                y,x=r+dr,c+dc
                while (y,x)!=(rr,cc):
                    if grid[y][x]==0: out[y][x]=1
                    y+=dr; x+=dc
        # Connect to a single 2 on an axis, provided it is not part of the diamond perimeter.
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=r+dr,c+dc
            while 0<=y<h and 0<=x<w and grid[y][x]==0:
                y+=dr; x+=dc
            if 0<=y<h and 0<=x<w and grid[y][x]==2 and grid[y][x] not in [grid[r+dr,c+dc] if 0<=r+dr<h and 0<=c+dc<w else -1]:
                pass
            # A line to an isolated 2 continues beyond the neighboring diamond edge.
            if 0<=y<h and 0<=x<w and grid[y][x]==2 and (abs(y-r)>1 or abs(x-c)>1):
                y,x=r+dr,c+dc
                while 0<=y<h and 0<=x<w and grid[y][x]==0:
                    out[y][x]=1; y+=dr; x+=dc
    return out
